insert into public.artists (id, name, genre_id, tag, bio, hometown, formed, socials, image_url, tracks) values
  ('moon-carrot', 'Moon Carrot', 'indie-rock', 'lo-fi', null, null, null, '{}'::jsonb, null, '[]'::jsonb),
  ('fallingislands', 'FallingIslands', 'electronic', 'synthwave', 'Falling Islands crafts shimmering synthwave soundscapes that pull from 80s retrofuturism and late-night neon aesthetics. The project began as solo studio experiments in a Queenstown apartment and has since evolved into a live A/V performance act. Their music feels like driving through an empty city at 3am with all the windows down.', 'Queenstown', 2017, '{"x": "https://x.com", "spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 1788047974, "title": "FREE THE VEIL"}, {"id": 1716514003, "title": "Netwlkr"}, {"id": 1524558608, "title": "Numbers in Disguise"}]'::jsonb),
  ('cloudy-yan', 'Cloudy Yan', 'mandopop', 'mandopop', 'Cloudy Yan is a balladeer whose hushed, intimate vocals float over spare piano and orchestral strings. Her songs dwell in the quiet spaces between heartbreak and acceptance, drawing from her years living between Singapore and Taipei. Each release feels like a handwritten letter you keep in a drawer and reread on rainy days.', 'Buona Vista', 2020, '{"spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "instagram": "https://instagram.com"}'::jsonb, null, '[]'::jsonb),
  ('forest-bloom', 'Forest Bloom', 'indie-rock', 'dream-pop', 'Forest Bloom makes hazy, reverb-drenched dream-pop that sounds like it was recorded inside a cloud. The duo met studying music at LASALLE and began layering guitar shimmer over drum machines in a Clementi practice room. Their songs are about daydreams, seasonal change, and the strange peace of being alone in a crowded city.', 'Clementi', 2019, '{"spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "instagram": "https://instagram.com"}'::jsonb, null, '[]'::jsonb),
  ('aiyna', 'ai.yna', 'pop', 'alt-pop', 'Aiyna makes alt-pop that refuses to sit still, jumping between wiry guitar hooks, layered synths, and lyrics that feel ripped from a private journal. She grew up in Jurong East absorbing everything from Björk to Mitski before finding her own voice in her early twenties. Her performances are visually striking and sonically unpredictable in the best way.', 'Jurong East', 2021, '{"x": "https://x.com", "spotify": "https://open.spotify.com", "instagram": "https://instagram.com"}'::jsonb, null, '[]'::jsonb),
  ('mindosphere', 'Mindosphere', 'electronic', 'house', 'Mindosphere is a house music producer and DJ rooted in the deeper, more meditative end of the dance music spectrum. Drawing from Chicago house, UK garage, and the ambient sounds of Singapore''s late-night hawker centres, his sets are built for long, hypnotic journeys on the dance floor. He runs a monthly night in Chinatown that has become essential listening for the local electronic community.', 'Chinatown', 2014, '{"spotify": "https://open.spotify.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[]'::jsonb),
  ('intrgnt', 'INTRGNT', 'electronic', 'techno', 'intrgnt is a techno producer operating at the harder, industrial end of Singapore''s electronic underground, releasing on limited-run vinyl and headlining basement clubs most people find by word of mouth. The project is intentionally anonymous — no press photos, no interviews — letting the music speak entirely on its own terms. Tracks are long, grinding, and engineered for maximum subwoofer damage.', 'Kallang', 2019, '{"x": "https://x.com", "spotify": "https://open.spotify.com"}'::jsonb, null, '[]'::jsonb),
  ('evanturetime', 'Evanturetime', 'electronic', 'edm', 'Evanture Time brings high-energy EDM to Singapore''s festival circuit, blending euphoric drops with melodic builds that keep dance floors moving until sunrise. Formed by two childhood friends from Tampines, they honed their craft playing underground warehouse parties before breaking onto the main stage. Their productions are known for tight sound design and crowd-tested energy.', 'Tampines', 2016, '{"spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 1579396392, "title": "if it''s with you"}, {"id": 1618195822, "title": "for any weather"}, {"id": 1383296000, "title": "White Lies"}]'::jsonb),
  ('kin-leonn', 'Kin Leonn', 'hip-hop', 'hip-hop', 'Kin Leonn is a Singapore hip-hop artist and producer whose dense, lyrical flow reflects life growing up in the heartlands with big city ambitions. He raps about code-switching, family pressure, and the grind of creative work in a country that doesn''t always have a lane for it. His self-produced instrumentals pull from boom-bap, trap, and the sounds of Singapore''s street corners.', 'Ang Mo Kio', 2016, '{"x": "https://x.com", "spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 1441994688, "title": "There Were Days"}, {"id": 1704274833, "title": "Missed Flight / New Friends"}]'::jsonb),
  ('loka-nada', 'Loka Nada', 'traditional', 'gamelan', 'Loka Nada is a gamelan ensemble dedicated to keeping Javanese and Balinese court music traditions alive in Singapore''s multicultural landscape. Founded by a group of second-generation Singaporeans who learned the instruments from community elders in Geylang Serai, they perform at cultural festivals, temples, and schools across the island. Their work bridges ritual heritage and contemporary audience curiosity.', 'Geylang Serai', 2015, '{"youtube": "https://youtube.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[]'::jsonb),
  ('kancing-rasa', 'Kancing Rasa', 'traditional', 'keroncong', 'Kancing Rasa revives the gentle, waltzing rhythms of keroncong — the Indonesian-Portuguese folk style — and gives them room to breathe in modern Singapore. The group brings together musicians trained in classical strings, traditional kroncong guitar, and modern jazz to create arrangements that feel both archival and alive. Their name translates loosely to ''the fastening of feeling'', which captures exactly what their music does.', 'Kampong Glam', 2016, '{"youtube": "https://youtube.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[]'::jsonb),
  ('sherman-zhuo', 'Sherman Zhuo', 'mandopop', 'mandopop', 'Sherman Zhuo writes Mandopop with a contemporary edge, weaving personal stories of identity and belonging into polished, radio-ready arrangements. Growing up in Toa Payoh with music playing constantly in his family home, he began writing his own songs at fifteen. His voice carries an emotional warmth that resonates with listeners across the Mandarin-speaking world.', 'Toa Payoh', 2018, '{"spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 1873881219, "title": "下一個你"}, {"id": 1676896623, "title": "hard to let you go"}, {"id": 1762573187, "title": "坠在原点的我"}]'::jsonb),
  ('krunkle', 'Krunkle', 'indie-rock', 'funk', 'Krunkle is a five-piece indie rock band with a deep funk groove, influenced equally by vintage Stax records and the chaos of Singapore HDB corridor jams. Their live shows are notoriously sweaty affairs packed with extended instrumental breakdowns and call-and-response crowd moments. They''ve been a fixture of the Esplanade Annexe scene since their earliest gigs.', 'Geylang', 2015, '{"x": "https://x.com", "spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 1719170173, "title": "Philia"}, {"id": 1719170176, "title": "Stale"}, {"id": 1719170327, "title": "Roofie Romance"}]'::jsonb),
  ('lullaboy', 'Lullaboy', 'pop', 'r&b', 'Lullaboy is a Singapore R&B singer-songwriter whose velvety falsetto and introspective lyrics have earned him a devoted online following. He started posting bedroom recordings to SoundCloud during his national service years and signed his first independent deal shortly after. His music sits at the intersection of neo-soul and contemporary R&B, always with a local emotional honesty.', 'Woodlands', 2018, '{"x": "https://x.com", "spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 1644633354, "title": "Shortcut To Heaven"}, {"id": 1557401161, "title": "someone like u"}, {"id": 1701539915, "title": "life with u"}]'::jsonb),
  ('riot-in-magenta', 'Riot In Magenta', 'electronic', 'synthpop', 'Riot in Magenta makes synthpop with sharp hooks and a dramatic flair, nodding to classic new wave while staying firmly planted in the present. The trio formed in Katong after a chance meeting at a record swap meet and quickly built a reputation for theatrical live shows with synchronized lighting rigs. Their music is big, bright, and unashamedly catchy.', 'Katong', 2017, '{"spotify": "https://open.spotify.com", "youtube": "https://youtube.com", "facebook": "https://facebook.com", "instagram": "https://instagram.com"}'::jsonb, null, '[{"id": 979774352, "title": "Told You So"}, {"id": 780579097, "title": "Lost"}, {"id": 780579100, "title": "Cloud"}]'::jsonb);
