insert into public.posts (id, user_id, username, title, content, tags, upvotes, downvotes, created_at, event_ids, artist_ids, images, song) values
  ('a0000000-0000-0000-0000-000000000004', null, 'crate_digger99', 'Is vinyl actually worth it, or is it just nostalgia?', 'I keep seeing people spend a lot on turntables and records. Does it really sound better than a good streaming setup, or is it mostly about the ritual?', array['vinyl', 'gear', 'discussion']::text[], 35, 19, '2026-10-18T08:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000007', null, 'festivalfanatic', 'Festival lineup predictions for next summer', 'Every year the rumours start early. Who do you think will headline? My bet is on a big reunion tour announcement.', array['festivals', 'predictions']::text[], 53, 6, '2026-10-19T12:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000008', null, 'nervous_nate', 'How do you handle stage fright?', 'I have my first open mic next week and my hands shake just thinking about it. Any tricks that worked for you?', array['performing', 'advice']::text[], 74, 0, '2026-10-19T20:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000009', null, 'gearhead_gus', 'Best budget audio interface under $150?', 'Just need two inputs, decent preamps, and low latency for recording guitar and vocals. Mac user. Don''t need anything fancy.', array['gear', 'recording', 'budget']::text[], 61, 3, '2026-10-20T02:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000012', null, 'latebloomer_lou', 'Learning guitar at 30, where do I start?', 'Never played an instrument before. Should I start with an acoustic or electric, and is it worth paying for lessons or are free videos enough?', array['guitar', 'beginners', 'learning']::text[], 58, 0, '2026-10-20T20:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000003', null, 'homestudio_hank', 'Tips for recording vocals at home without a studio', 'My bedroom has bare walls and a lot of echo. I''ve tried hanging blankets but the recordings still sound boxy. What''s the cheapest way to get a usable vocal take?', array['recording', 'vocals', 'tips']::text[], 67, 1, '2026-10-18T00:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000013', null, 'weddingband_will', 'Looking for a keyboardist for wedding gigs', 'Steady weekend work, paid, covering pop and soul classics. Need someone who can sight-read charts and sing backing vocals.', array['lfg', 'keys', 'gigs']::text[], 19, 0, '2026-10-21T00:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000005', null, 'bassline_ben', 'LFG: bassist for a jazz fusion jam night', 'Starting a monthly jam night at a small bar. Looking for a bassist comfortable with groove and some odd time signatures. Upright or electric, either is fine.', array['lfg', 'bass', 'jazz']::text[], 28, 0, '2026-10-18T20:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000002', null, 'lofi_lena', 'What are you listening to this week?', null, array['discussion', 'weekly']::text[], 118, 4, '2026-10-17T08:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000015', null, 'mixdown_mo', 'Mixing tip: stop boosting highs, cut the mud instead', 'Most muddy mixes need less low-mid, not more treble. Try cutting around 200-400 Hz on guitars and keys before reaching for the high shelf. Your mix will sound cleaner without getting harsh.', array['mixing', 'production', 'tips']::text[], 136, 4, '2026-10-21T06:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('40ad5317-6484-401b-9d2a-9d78149d731e', null, 'Music fan', 'asd', 'asdad', array['ad', 'da', 'dasd', 'wdawd', 'daw']::text[], 0, 0, '2026-10-21T10:26:20.320542+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000001', null, 'vinylvera', 'Looking for a drummer for a post-punk band', 'We''re a three-piece (guitar, bass, vocals) with about eight originals written. Rehearsing twice a week on weekday evenings. Influences are Joy Division, Idles and Fontaines D.C. Experience with click tracks would be great.', array['lfg', 'drums', 'post-punk']::text[], 42, 2, '2026-10-16T08:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000014', null, 'album_archivist', 'Share your favourite album of the year so far', null, array['albums', 'discussion', 'weekly']::text[], 102, 5, '2026-10-21T03:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000006', null, 'discover_dee', 'Underrated artists you discovered through Riffle', null, array['discovery', 'artists']::text[], 96, 2, '2026-10-19T06:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000011', null, 'frontrow_fran', 'Concert etiquette: phones up or phones down?', null, array['concerts', 'etiquette', 'discussion']::text[], 89, 22, '2026-10-20T14:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
  ('a0000000-0000-0000-0000-000000000010', null, 'dreamy_dani', 'Anyone want to start a bedroom pop collective?', 'I make dreamy bedroom pop on my laptop and would love to swap stems, trade feedback and maybe release a compilation together.', array['lfg', 'bedroom-pop', 'collab']::text[], 31, 1, '2026-10-20T08:55:19.562814+00:00', '{}'::text[], '{}'::text[], '{}'::text[], null),
