insert into public.replies (id, post_id, parent_id, user_id, username, content, upvotes, downvotes, created_at) values
  ('85b794f1-392a-4420-a558-ffc80bb7322f', 'a0000000-0000-0000-0000-000000000001', null, null, 'stickyfingers', 'Sent you a DM! I''ve been playing post-punk for six years and have my own kit.', 0, 0, '2026-10-17T04:55:19.562814+00:00'),
  ('8db71c5b-6bac-4d00-8700-248875ffb6e2', 'a0000000-0000-0000-0000-000000000001', null, null, 'amp_and_ale', 'Do you have a demo link? Would love to hear the originals before I reach out.', 0, 0, '2026-10-18T10:55:19.562814+00:00'),
  ('6758e5f5-9be2-4ed9-8b7d-7b2b108a82a1', 'a0000000-0000-0000-0000-000000000002', null, null, 'midnightmixtape', 'On repeat: the new Khruangbin record. Perfect for working late.', 0, 0, '2026-10-17T14:55:19.562814+00:00'),
  ('bc4b80b2-ae1a-4ff9-adf8-fa035b21bc7a', 'a0000000-0000-0000-0000-000000000002', null, null, 'cassette_kid', 'Digging through old 90s shoegaze playlists. Slowdive never misses.', 0, 0, '2026-10-19T16:55:19.562814+00:00'),
  ('7db730fe-77db-4681-b238-a17167bc94c2', 'a0000000-0000-0000-0000-000000000003', null, null, 'pop_filter_pete', 'Record in a wardrobe full of clothes. Genuinely the best budget vocal booth. Face the clothes, not the open door.', 0, 0, '2026-10-18T20:55:19.562814+00:00'),
  ('c7fddec4-526a-4006-8549-9081d998f929', 'a0000000-0000-0000-0000-000000000005', null, null, 'fretless_fiona', 'I play fretless electric and love fusion. When is the first night?', 0, 0, '2026-10-20T02:55:19.562814+00:00'),
  ('f0b18ece-440a-481e-8c14-58ed95584444', 'a0000000-0000-0000-0000-000000000006', null, null, 'static_sunrise', 'Found a dream pop duo through the artists page last month. Still can''t stop playing their EP.', 0, 0, '2026-10-19T11:55:19.562814+00:00'),
  ('25daeb90-1205-4ce6-acf4-15f8311d7ab7', 'a0000000-0000-0000-0000-000000000006', null, null, 'needle_drop_nina', 'A local folk trio I''d never have heard otherwise. Went to their show and bought a shirt.', 0, 0, '2026-10-20T12:55:19.562814+00:00'),
  ('d1298e20-9d5f-4886-a500-93c609d19f24', 'a0000000-0000-0000-0000-000000000007', null, null, 'mainstage_mike', 'Hoping for at least one big electronic headliner this time. The lineups have been too rock-heavy.', 0, 0, '2026-10-20T02:55:19.562814+00:00'),
  ('8175aee6-01c0-4d6b-b1a1-19c35922c710', 'a0000000-0000-0000-0000-000000000007', null, null, 'wristband_wendy', 'Reunion rumours are always wishful thinking, but I''d camp out for that one.', 0, 0, '2026-10-20T22:55:19.562814+00:00'),
  ('f0d8798e-3cf6-4ffa-bc42-4a0714ad89c2', 'a0000000-0000-0000-0000-000000000008', null, null, 'open_mic_olivia', 'Play your first song on autopilot: pick the one you know best. Once that''s done the nerves drop a lot.', 0, 0, '2026-10-20T12:55:19.562814+00:00'),
  ('0ddad490-4909-4ab4-9891-2559508cb8a5', 'a0000000-0000-0000-0000-000000000009', null, null, 'preamp_priya', 'Focusrite Scarlett 2i2 is the obvious pick and rarely a bad one. Look for a used one to save money.', 0, 0, '2026-10-20T07:55:19.562814+00:00'),
  ('cf854681-c47f-488d-8234-571d6d993c58', 'a0000000-0000-0000-0000-000000000009', null, null, 'studio_sam', 'Second the Scarlett. The Audient EVO 4 is also great if you want something smaller.', 0, 0, '2026-10-20T20:55:19.562814+00:00'),
  ('c6f64d19-2e4f-416d-8c22-bb960fc2327c', 'a0000000-0000-0000-0000-000000000011', null, null, 'livemusic_larry', 'One quick clip is fine. Filming the whole set while blocking everyone behind you is not.', 0, 0, '2026-10-20T22:55:19.562814+00:00'),
  ('67fc677c-03e9-408b-80a0-cfda950aa930', 'a0000000-0000-0000-0000-000000000011', null, null, 'tallguy_tom', 'Phones down for the slow songs at least. The atmosphere is half the experience.', 0, 0, '2026-10-21T05:55:19.562814+00:00'),
  ('96425d68-952c-411d-90b8-755bc0abbcbb', 'a0000000-0000-0000-0000-000000000012', null, null, 'chordchaser', 'Pick whichever type of music you actually want to play. Motivation matters more than the instrument. A few lessons early on help with bad habits.', 0, 0, '2026-10-21T02:55:19.562814+00:00'),
  ('0becb4da-520d-4fa4-993f-788bf825ecfc', 'a0000000-0000-0000-0000-000000000014', null, null, 'tracklist_tess', 'Still can''t beat the debut from that Glasgow synth-pop group. Every track is a keeper.', 0, 0, '2026-10-21T06:55:19.562814+00:00'),
  ('571664a5-0f4d-4a4a-9145-451dd2f9e141', 'a0000000-0000-0000-0000-000000000015', null, null, 'eq_enthusiast', 'This changed my mixes. Also high-pass everything that doesn''t need sub bass.', 0, 0, '2026-10-21T07:25:19.562814+00:00'),
  ('1c31b2f8-a720-4d15-9c4f-046c3281c006', 'a0000000-0000-0000-0000-000000000015', null, null, 'bounce_beth', 'Good advice, but check on a few different speakers. Cutting too much makes things thin.', 0, 0, '2026-10-21T08:25:19.562814+00:00'),
  ('d96e1d02-a114-4486-99b1-e8695139b98d', 'a0000000-0000-0000-0000-000000000001', '8db71c5b-6bac-4d00-8700-248875ffb6e2', null, 'sample_user', '[sample] Good point, I''d add that this works even better with a little practice.', 0, 0, '2026-10-18T11:05:19.562814+00:00'),
  ('a6617305-c277-489d-8976-6653b4ce81cb', 'a0000000-0000-0000-0000-000000000003', '7db730fe-77db-4681-b238-a17167bc94c2', null, 'sample_user', '[sample] Good point, I''d add that this works even better with a little practice.', 0, 0, '2026-10-18T21:05:19.562814+00:00'),
